import requests
import json

class DogecoinAPI:
    """
    A class to interact with the Dogecoin API for sending and receiving transactions.
    """

    def __init__(self, api_url):
        """
        Initializes the DogecoinAPI with the given API URL.

        :param api_url: The base URL of the Dogecoin API.
        """
        self.api_url = api_url

    def get_balance(self, address):
        """
        Retrieves the balance of a given Dogecoin address.

        :param address: The Dogecoin address to check the balance for.
        :return: The balance in Dogecoin or an error message.
        """
        try:
            response = requests.get(f"{self.api_url}/address/{address}/balance")
            response.raise_for_status()  # Raise an error for bad responses
            return response.json().get('balance', 0)
        except requests.RequestException as e:
            return f"Error retrieving balance: {e}"

    def send_transaction(self, from_address, to_address, amount):
        """
        Sends a transaction from one Dogecoin address to another.

        :param from_address: The address sending the Dogecoin.
        :param to_address: The address receiving the Dogecoin.
        :param amount: The amount of Dogecoin to send.
        :return: Transaction ID or an error message.
        """
        transaction_data = {
            "from": from_address,
            "to": to_address,
            "amount": amount
        }

        try:
            response = requests.post(f"{self.api_url}/send", json=transaction_data)
            response.raise_for_status()  # Raise an error for bad responses
            return response.json().get('transaction_id', 'Transaction failed')
        except requests.RequestException as e:
            return f"Error sending transaction: {e}"

